-- Modify "order_items" table
ALTER TABLE `order_items` ADD COLUMN `delivery_kind` varchar(255) NOT NULL DEFAULT "card", ADD COLUMN `sms_product` json NULL, ADD COLUMN `sms_purchase_snapshot` longtext NULL;
-- Modify "products" table
ALTER TABLE `products` ADD COLUMN `delivery_kind` varchar(255) NOT NULL DEFAULT "card", ADD COLUMN `sms_product` json NULL;
-- Create "sms_intents" table
CREATE TABLE `sms_intents` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `order_id` bigint unsigned NOT NULL, `order_item_id` bigint unsigned NOT NULL, `user_id` bigint unsigned NOT NULL, `connection_id` bigint unsigned NOT NULL, `connection_identity` varchar(255) NOT NULL, `request_no` varchar(64) NOT NULL, `request_json` longtext NOT NULL, `request_hash` varchar(64) NOT NULL, `upstream_order_id` varchar(255) NULL, `phase` varchar(255) NOT NULL DEFAULT "purchase", `state` varchar(255) NOT NULL DEFAULT "allocating", `session_id` varchar(255) NOT NULL DEFAULT "", `version` bigint NOT NULL DEFAULT 0, `sms_revision` bigint NOT NULL DEFAULT 0, `snapshot_cipher` blob NULL, `received` bool NOT NULL DEFAULT 0, `can_cancel` bool NOT NULL DEFAULT 0, `can_finish` bool NOT NULL DEFAULT 0, `charged_amount` bigint NOT NULL DEFAULT 0, `settlement_state` varchar(255) NOT NULL DEFAULT "", `refunded_amount` bigint NOT NULL DEFAULT 0, `refund_reference` varchar(255) NOT NULL DEFAULT "", `rejected_receipt` bool NOT NULL DEFAULT 0, `retail_refund_state` varchar(255) NOT NULL DEFAULT "none", `refund_id` bigint unsigned NOT NULL DEFAULT 0, `next_run_at` bigint NOT NULL DEFAULT 0, `lease_until` bigint NOT NULL DEFAULT 0, `lease_token` varchar(255) NOT NULL DEFAULT "", `attempts` bigint NOT NULL DEFAULT 0, `last_error` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), UNIQUE INDEX `smsintent_connection_id_upstream_order_id` (`connection_id`, `upstream_order_id`), UNIQUE INDEX `smsintent_order_item_id` (`order_item_id`), INDEX `smsintent_phase_next_run_at_lease_until` (`phase`, `next_run_at`, `lease_until`), UNIQUE INDEX `smsintent_request_no` (`request_no`), INDEX `smsintent_subsite_id_user_id_order_id` (`subsite_id`, `user_id`, `order_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "sms_operations" table
CREATE TABLE `sms_operations` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `intent_id` bigint unsigned NOT NULL, `operation_id` varchar(64) NOT NULL, `action` varchar(255) NOT NULL, `status` varchar(255) NOT NULL DEFAULT "pending", `error_code` varchar(255) NOT NULL DEFAULT "", `attempts` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `smsoperation_intent_id_status` (`intent_id`, `status`), UNIQUE INDEX `smsoperation_operation_id` (`operation_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
